<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { ArrowDown, ArrowUpRight, Clock3, Eye, Heart, Sparkles } from 'lucide-vue-next'
type Post={id:number,title:string,summary:string,category:string,cover:string,readMinutes:number,views:number,likes:number,createdAt:string}
const posts=ref<Post[]>([]), loading=ref(true), error=ref('')
onMounted(async()=>{try{const r=await fetch('/api/posts');if(!r.ok)throw Error('文章加载失败，请稍后重试');posts.value=await r.json()}catch(e){error.value=String(e)}finally{loading.value=false}})
</script>
<template><section class="hero"><div class="hero-copy"><span class="eyebrow"><Sparkles :size="14"/> 一处安放心事的角落</span><h1>写给日常，<br><em>也写给远方。</em></h1><p>这里收藏生活的细碎片段，也记录那些<br>值得慢慢讲述的故事。</p><a class="hero-link" href="#articles">开始阅读 <ArrowDown :size="15"/></a></div><div class="hero-art"><div class="art-frame"><img src="https://images.unsplash.com/photo-1470252649378-9c29740c9fa8?auto=format&fit=crop&w=1100&q=85" alt="晨光照耀的山谷"/><div class="image-caption">MORNING NOTES <span>— 01 / 26</span></div></div><span class="art-stamp">SINCE<br>2024</span><span class="art-scribble">✳</span></div><div class="hero-bottom"><span>SCROLL TO EXPLORE</span><span class="line"></span><span>01 — 03</span></div></section><section id="articles" class="articles"><div class="section-head"><div><span class="eyebrow">THE JOURNAL</span><h2>最近的文章<span class="count">{{ posts.length.toString().padStart(2,'0') }}</span></h2></div><a class="all-link" href="#articles">浏览全部 <ArrowUpRight :size="16"/></a></div><div v-if="loading" class="loading">正在翻开新的一页…</div><div v-else class="post-grid"><article v-for="(post,i) in posts" :key="post.id" class="post-card"><div class="post-image"><img :src="`https://images.unsplash.com/${post.cover}?auto=format&fit=crop&w=900&q=80`" :alt="post.title"/><span class="post-index">0{{i+1}}</span></div><div class="post-meta"><span>{{post.category}}</span><span>{{post.createdAt}}</span></div><h3><RouterLink :to='`/posts/${post.id}`'>{{post.title}}</RouterLink></h3><p>{{post.summary}}</p><div class="post-foot"><span><Clock3 :size="14"/> {{post.readMinutes}} 分钟阅读</span><span><Eye :size="14"/> {{post.views}}</span><span><Heart :size="14"/> {{post.likes}}</span></div></article></div><p v-if="error" class="error">{{error}}</p></section><section id="about" class="note"><span class="eyebrow">A SMALL NOTE</span><p>“生活不是等待风暴过去，<br>而是学会在雨中跳舞。”</p><span class="note-by">— Vivian Greene</span></section></template>
